begin;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function pg_temp.denied(stmt text,expected text,label text) returns void language plpgsql as $$begin begin execute stmt;exception when others then if position(expected in sqlerrm)=0 then raise exception 'FAIL % expected %, got %',label,expected,sqlerrm;end if;raise notice 'PASS %',label;return;end;raise exception 'FAIL unexpectedly allowed %',label;end$$;
select set_config('request.jwt.claim.sub','f9200000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claim.role','authenticated',true);
insert into branches(id,code,name) values('cb710000-0000-0000-0000-000000000001','SUPER-OTHER','Synthetic other branch');
insert into auth.users(id,email) values('cb720000-0000-0000-0000-000000000001','super-reader@example.invalid');
insert into profiles(id,full_name,branch_id,active) values('cb720000-0000-0000-0000-000000000001','Synthetic reader','cb710000-0000-0000-0000-000000000001',true);
insert into roles(code,name) values('SUPER_AUDIT_READER','Synthetic reader');
insert into role_permissions(role_id,permission_code) select id,'ISO_COMPLIANCE_VIEW' from roles where code='SUPER_AUDIT_READER';
insert into user_roles(user_id,role_id,branch_id) select 'cb720000-0000-0000-0000-000000000001',id,'cb710000-0000-0000-0000-000000000001' from roles where code='SUPER_AUDIT_READER';
grant execute on all functions in schema pg_temp to authenticated,anon;
set local role authenticated;
select pg_temp.ok((select count(*)=3 and bool_and(enabled) from vw_my_module_access where route_key in ('maintenance','congresses','supplytransfers')),'super opens maintenance congresses and supply transfers');
select pg_temp.ok(not exists(select 1 from app_permissions where active and not has_permission(permission_code)),'super receives all active permissions including new ones');
select pg_temp.ok(can_access_branch('cb710000-0000-0000-0000-000000000001'),'super scope includes other branches');
insert into audit_criteria_catalog(id,clause_reference,criterion_code,criterion_summary) values('cb730000-0000-0000-0000-000000000001','TEST','SUPER-TEST-CRITERION','Synthetic review');
select iso_clause_assessment_upsert('cb730000-0000-0000-0000-000000000001','cb710000-0000-0000-0000-000000000001','CUMPLE',auth.uid(),'Synthetic evidence',current_date+7) as assessment_id \gset
insert into iso_clause_evidence(assessment_id,title,source_reference,captured_by) values(:'assessment_id','Synthetic document','TEST-EVIDENCE',auth.uid());
select pg_temp.ok(exists(select 1 from iso_clause_evidence where assessment_id=:'assessment_id'),'super records ISO assessment and evidence under invoker RLS');
select pg_temp.denied(format('select iso_clause_assessment_create_nc(%L,auth.uid(),current_date+1,''Synthetic'')',:'assessment_id'),'NO_CUMPLE','super cannot create NC from compliant ISO clause');
select iso_clause_assessment_upsert('cb730000-0000-0000-0000-000000000001','cb710000-0000-0000-0000-000000000001','NO_CUMPLE',auth.uid(),'Synthetic finding',current_date+7);
select pg_temp.ok(iso_clause_assessment_create_nc(:'assessment_id',auth.uid(),current_date+7,'Synthetic NC') is not null,'super creates ISO NC after valid noncompliance');
insert into branch_inspections(id,inspection_code,branch_id,inspector_id) values('cb740000-0000-0000-0000-000000000001','SUPER-TEST-INSPECTION','cb710000-0000-0000-0000-000000000001',auth.uid());
insert into inspection_findings(id,inspection_id,section_name,criterion,result) values('cb750000-0000-0000-0000-000000000001','cb740000-0000-0000-0000-000000000001','Synthetic','Synthetic criterion','NC');
select pg_temp.denied($q$select inspection_finding_create_capa('cb750000-0000-0000-0000-000000000001','Plan',auth.uid(),current_date+7)$q$,'NC vinculada','super cannot skip linked NC before CAPA');
select pg_temp.ok(inspection_finding_to_nonconformity('cb750000-0000-0000-0000-000000000001',auth.uid(),current_date+7) is not null,'super creates inspection NC within normal workflow');
select pg_temp.denied($q$select inspection_finding_create_capa('cb750000-0000-0000-0000-000000000001','',auth.uid(),current_date+7)$q$,'Plan de acción obligatorio','super still requires CAPA action plan');
select pg_temp.ok(inspection_finding_create_capa('cb750000-0000-0000-0000-000000000001','Synthetic action plan',auth.uid(),current_date+7) is not null,'super creates inspection CAPA with mandatory plan');
select pg_temp.denied($q$select audit_finding_to_nonconformity('cb750000-0000-0000-0000-000000000099',auth.uid(),current_date+7)$q$,'Hallazgo no encontrado','super passes internal-audit role gate but missing finding is still rejected');
select pg_temp.ok((select bool_and(not prosecdef) from pg_proc where oid in ('inspection_finding_to_nonconformity(uuid,uuid,date)'::regprocedure,'inspection_finding_create_capa(uuid,text,uuid,date)'::regprocedure,'audit_finding_to_nonconformity(uuid,uuid,date)'::regprocedure,'audit_finding_create_capa(uuid,text,uuid,date)'::regprocedure,'iso_clause_assessment_upsert(uuid,uuid,text,uuid,text,date)'::regprocedure,'iso_clause_assessment_create_nc(uuid,uuid,date,text)'::regprocedure)),'all six corrected functions remain invoker');
select pg_temp.ok(not has_function_privilege('anon','hc_generate_management_alerts(date)','execute') and has_function_privilege('authenticated','hc_generate_management_alerts(date)','execute'),'existing management alert service preserves caller ACL');
select pg_temp.ok(position('wf_active_actor' in pg_get_functiondef('hc_generate_management_alerts(date)'::regprocedure))>0,'management alert service recognizes active super without adding caller or schedule');
select pg_temp.ok(not has_function_privilege('anon','iso_clause_assessment_upsert(uuid,uuid,text,uuid,text,date)','execute'),'anonymous ISO execution stays denied');
select set_config('request.jwt.claim.sub','cb720000-0000-0000-0000-000000000001',true);
select pg_temp.ok(not has_permission('ACCESS_ADMIN'),'ordinary reader does not gain administration');
select pg_temp.denied($q$select iso_clause_assessment_upsert('cb730000-0000-0000-0000-000000000001','cb710000-0000-0000-0000-000000000001','CUMPLE',auth.uid(),'Forbidden',current_date+1)$q$,'Rol no autorizado','ordinary reader does not gain ISO writes');
select pg_temp.ok(not exists(select 1 from role_module_access rm join roles r on r.id=rm.role_id where r.code='SUPER_AUDIT_READER' and route_key in ('maintenance','congresses','supplytransfers') and enabled),'new windows do not grant ordinary roles access');
reset role;
update profiles set active=false where id='f9200000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','f9200000-0000-0000-0000-000000000001',true);
select pg_temp.ok(not has_permission('ACCESS_ADMIN') and not can_access_branch('cb710000-0000-0000-0000-000000000001'),'inactive super has no permission or branch scope');
select pg_temp.denied($q$select iso_clause_assessment_upsert('cb730000-0000-0000-0000-000000000001',null,'CUMPLE',auth.uid(),'Forbidden',current_date+1)$q$,'Rol no autorizado','inactive super cannot use global ISO role alternative');
rollback;
